window.CIVIL_SET_DATA["past-08"] = {"title":"Past Paper Set 8","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-08-005","src":"PAST-08-005","text":"A brick is soaked in water before use","options":[{"key":"a","text":"To wash dust"},{"key":"b","text":"To prevent moisture loss from mortar"},{"key":"c","text":"Even spreading of mortar"},{"key":"d","text":"All"}],"answer":"d","explanation":"Soaking removes dust and stops the dry, porous brick from sucking water out of the mortar. The mortar then spreads evenly, hydrates properly and bonds well.","marks":1,"source":{"kind":"past","set":8,"question":5,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q5 · 1 mark"},"topic":"ACiE0103"},{"id":"PAST-08-006","src":"PAST-08-006","text":"The indentation on the surface of a brick is called","options":[{"key":"a","text":"Frog"},{"key":"b","text":"Strike"},{"key":"c","text":"Spike"},{"key":"d","text":"All"}],"answer":"a","explanation":"The frog is the depression on the face of a brick. It forms a key for the mortar, reduces weight and carries the manufacturer's mark.","marks":1,"source":{"kind":"past","set":8,"question":6,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q6 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-08-016","src":"PAST-08-016","text":"The MOI of a semicircle about its base is","options":[{"key":"a","text":"πD<sup>4</sup>/128"},{"key":"b","text":"πD<sup>4</sup>/16"},{"key":"c","text":"πD<sup>4</sup>/64"},{"key":"d","text":"πD<sup>4</sup>/32"}],"answer":"a","explanation":"About its diameter, a semicircle has half the circle's \\(I\\): \\[\\dfrac{1}{2} \\times \\dfrac{\\pi D^4}{64} = \\dfrac{\\pi D^4}{128} = \\dfrac{\\pi r^4}{8}\\]","marks":1,"source":{"kind":"past","set":8,"question":16,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q16 · 1 mark"},"topic":"ACiE0104"},{"id":"PAST-08-018","src":"PAST-08-018","text":"The binding wire quantity in 1 quintal of reinforcement is","options":[{"key":"a","text":"1 kg"},{"key":"b","text":"5 kg"},{"key":"c","text":"2 kg"},{"key":"d","text":"10 kg"}],"answer":"a","explanation":"Estimates usually allow about 1 kg of binding wire (about 0.8–1%) per quintal (100 kg) of reinforcement.","marks":1,"source":{"kind":"past","set":8,"question":18,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q18 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-08-019","src":"PAST-08-019","text":"How many satellites are used for GPS by the US Department of Defense?","options":[{"key":"a","text":"24"},{"key":"b","text":"18"},{"key":"c","text":"20"},{"key":"d","text":"22"}],"answer":"a","explanation":"The GPS constellation was designed for 24 operational satellites in six orbital planes, so at least four are visible anywhere at any time. Spares are also kept in orbit.","marks":1,"source":{"kind":"past","set":8,"question":19,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q19 · 1 mark"},"topic":"ACiE0105"},{"id":"PAST-08-047","src":"PAST-08-047","text":"The maximum limit of weight of fiberboards is","options":[{"key":"a","text":"960 kg/m<sup>3</sup>"},{"key":"b","text":"1960 kg/m<sup>3</sup>"},{"key":"c","text":"2460 kg/m<sup>3</sup>"},{"key":"d","text":"2960 kg/m<sup>3</sup>"}],"answer":"a","explanation":"Fibre boards (reconstructed wood) are pressed wood-fibre sheets. Even the hard pressed grades weigh at most about 960 kg per m<sup>3</sup>, depending on the pressure used in manufacture.","marks":1,"source":{"kind":"past","set":8,"question":47,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q47 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-08-048","src":"PAST-08-048","text":"Before plastering, the surface has to be","options":[{"key":"a","text":"rough"},{"key":"b","text":"smooth"},{"key":"c","text":"cemented"},{"key":"d","text":"watered"}],"answer":"a","explanation":"Joints are raked and the surface is roughened (and wetted) before plastering so that the plaster keys into it and bonds well.","marks":1,"source":{"kind":"past","set":8,"question":48,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q48 · 1 mark"},"topic":"ACiE0103"},{"id":"PAST-08-062","src":"PAST-08-062","text":"What is the right face zenith angle if the left face zenith angle is 98°30'30\"?","options":[{"key":"a","text":"261°29'30\""},{"key":"b","text":"178°30'30\""},{"key":"c","text":"81°29'30\""},{"key":"d","text":"98°30'30\""}],"answer":"a","explanation":"With a full-circle vertical scale, the two face readings sum to 360°: 360° − 98°30′30″ = 261°29′30″.","marks":2,"source":{"kind":"past","set":8,"question":62,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q62 · 2 marks"},"topic":"ACiE0105"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-08-007","src":"PAST-08-007","text":"What is the formula for the active earth pressure coefficient?","options":[{"key":"a","text":"(1+sinφ)/(1−sinφ)"},{"key":"b","text":"(1−sinφ)/(1+sinφ)"},{"key":"c","text":"(1+sin<sup>2</sup>φ)/(1−sin<sup>2</sup>φ)"},{"key":"d","text":"(1−sin<sup>2</sup>φ)/(1+sin<sup>2</sup>φ)"}],"answer":"b","explanation":"Rankine's active coefficient is \\[\\begin{aligned} K_a &amp;= \\dfrac{1 - \\sin\\phi}{1 + \\sin\\phi} \\\\ &amp;= \\tan^2\\left(45^\\circ - \\dfrac{\\phi}{2}\\right) \\end{aligned}\\] The passive coefficient \\(K_p\\) is its reciprocal.","marks":1,"source":{"kind":"past","set":8,"question":7,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q7 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-08-021","src":"PAST-08-021","text":"The bearing capacity formula for cohesionless soil from a plate load test is","options":[{"key":"a","text":"q<sub>f</sub> = q<sub>p</sub> × B<sub>f</sub>/B<sub>p</sub>"},{"key":"b","text":"S<sub>p</sub> × B<sub>p</sub>/B<sub>f</sub>"},{"key":"c","text":"S<sub>f</sub> = S<sub>p</sub>"},{"key":"d","text":"S<sub>f</sub> = S<sub>p</sub>[B<sub>f</sub>(B<sub>p</sub>+0.3)/B<sub>p</sub>(B<sub>f</sub>+0.3)]<sup>2</sup>"}],"answer":"a","explanation":"For sands, the ultimate bearing capacity increases in proportion to width: \\[q_f = q_p\\dfrac{B_f}{B_p}\\] Option (d) is the settlement relation for sands, and \\(S_f = S_p\\dfrac{B_f}{B_p}\\) is used for clays.","marks":1,"source":{"kind":"past","set":8,"question":21,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q21 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-08-024","src":"PAST-08-024","text":"The direction of seepage water is","options":[{"key":"a","text":"perpendicular to the equipotential line"},{"key":"b","text":"perpendicular to the stream line"},{"key":"c","text":"parallel to the equipotential line"},{"key":"d","text":"along the direction of gravity"}],"answer":"a","explanation":"Seepage follows flow lines, which cross equipotential lines at right angles in an isotropic soil. Flow goes from higher to lower total head.","marks":1,"source":{"kind":"past","set":8,"question":24,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q24 · 1 mark"},"topic":"ACiE0202"},{"id":"PAST-08-025","src":"PAST-08-025","text":"Bearing capacity is calculated from","options":[{"key":"a","text":"SPT value"},{"key":"b","text":"Pile load test"},{"key":"c","text":"Shear strength parameters"},{"key":"d","text":"All of the above"}],"answer":"d","explanation":"Bearing capacity can be found from shear strength parameters (Terzaghi's theory), from in-situ tests such as SPT N-values and plate or pile load tests, and from building codes.","marks":1,"source":{"kind":"past","set":8,"question":25,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q25 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-08-036","src":"PAST-08-036","text":"The shear strength of a cohesionless soil doesn't depend on","options":[{"key":"a","text":"rate of loading"},{"key":"b","text":"stress history"},{"key":"c","text":"confining pressure"},{"key":"d","text":"force"}],"answer":"a","explanation":"Sands drain almost instantly, so their strength \\(\\tau = \\sigma'\\tan\\phi'\\) is practically independent of the rate of loading. It does depend on confining (normal) pressure and on density and stress history. The source key's (d) 'force' is not meaningful.","marks":1,"source":{"kind":"past","set":8,"question":36,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q36 · 1 mark"},"topic":"ACiE0203"},{"id":"PAST-08-041","src":"PAST-08-041","text":"What is the value of the coefficient of uniformity for a well graded sand?","options":[{"key":"a","text":"&gt;4"},{"key":"b","text":"&gt;6"},{"key":"c","text":"1 to 3"},{"key":"d","text":"&gt;10"}],"answer":"b","explanation":"A sand is well graded when \\[C_u = \\dfrac{D_{60}}{D_{10}} \\gt 6\\] and \\(C_c\\) is between 1 and 3. For gravel the limit is \\(C_u \\gt 4\\).","marks":1,"source":{"kind":"past","set":8,"question":41,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q41 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-08-064","src":"PAST-08-064","text":"The settlement formula for cohesionless soil from a plate load test is","options":[{"key":"a","text":"B<sub>f</sub>/B<sub>p</sub>"},{"key":"b","text":"S<sub>p</sub> × B<sub>p</sub>/B<sub>f</sub>"},{"key":"c","text":"S<sub>f</sub> = S<sub>p</sub>"},{"key":"d","text":"S<sub>f</sub> = S<sub>p</sub>[B<sub>f</sub>(B<sub>p</sub>+0.3)/B<sub>p</sub>(B<sub>f</sub>+0.3)]<sup>2</sup>"}],"answer":"d","explanation":"Terzaghi and Peck's relation for sands, with \\(B\\) in metres, is \\[S_f = S_p\\left[\\dfrac{B_f(B_p + 0.3)}{B_p(B_f + 0.3)}\\right]^2\\] For clays \\(S_f = S_p\\dfrac{B_f}{B_p}\\).","marks":2,"source":{"kind":"past","set":8,"question":64,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q64 · 2 marks"},"topic":"ACiE0206"},{"id":"PAST-08-065","src":"PAST-08-065","text":"What is the formula to compute the dry density of soil?","options":[{"key":"a","text":"γ/(1+w)"},{"key":"b","text":"(1−n<sub>a</sub>)Gγ<sub>w</sub>/(1+wG)"},{"key":"c","text":"Gγ<sub>w</sub>/(1+e)"},{"key":"d","text":"All of the above"}],"answer":"d","explanation":"Each form is a dry unit weight: \\[\\begin{aligned} \\gamma_d &amp;= \\dfrac{\\gamma}{1 + w} = \\dfrac{G\\gamma_w}{1 + e} \\\\ &amp;= \\dfrac{(1 - n_a)G\\gamma_w}{1 + wG} \\end{aligned}\\] The paper prints (c) with an extra factor \\((1 + w)\\) in the numerator, which is the bulk unit weight; it is corrected here to the intended dry form.","marks":2,"source":{"kind":"past","set":8,"question":65,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q65 · 2 marks"},"topic":"ACiE0201"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-08-026","src":"PAST-08-026","text":"In defining the Froude number, which depth parameter is used?","options":[{"key":"a","text":"Hydraulic mean depth"},{"key":"b","text":"Hydraulic radius"},{"key":"c","text":"Critical depth"},{"key":"d","text":"Depth"}],"answer":"a","explanation":"The Froude number is \\[\\text{Fr} = \\dfrac{V}{\\sqrt{gD}}, \\qquad D = \\dfrac{A}{T}\\] where \\(D\\) is the hydraulic mean depth. For a wide rectangular channel it equals the flow depth.","marks":1,"source":{"kind":"past","set":8,"question":26,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q26 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-08-027","src":"PAST-08-027","text":"The bulk modulus of a liquid","options":[{"key":"a","text":"is independent of temperature"},{"key":"b","text":"increases with pressure"},{"key":"c","text":"is independent of pressure and viscosity"},{"key":"d","text":"is larger when the fluid is more compressible"}],"answer":"b","explanation":"The bulk modulus \\[K = -V\\dfrac{dp}{dV}\\] rises as the liquid is compressed (it grows with pressure) and varies with temperature. A larger \\(K\\) means a less compressible fluid.","marks":1,"source":{"kind":"past","set":8,"question":27,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q27 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-08-028","src":"PAST-08-028","text":"The rational method is applicable for","options":[{"key":"a","text":"duration of rainfall &lt; time of concentration"},{"key":"b","text":"duration of rainfall &gt; time of concentration"},{"key":"c","text":"duration of rainfall = time of concentration"},{"key":"d","text":"duration doesn't depend on the time of concentration"}],"answer":"c","explanation":"The rational formula \\[Q = \\dfrac{CIA}{360}\\] gives the peak when the whole catchment contributes, i.e. for a storm lasting at least the time of concentration. The design intensity is taken for a duration equal to \\(t_c\\).","marks":1,"source":{"kind":"past","set":8,"question":28,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q28 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-08-033","src":"PAST-08-033","text":"Buoyancy force is","options":[{"key":"a","text":"force on submerged body"},{"key":"b","text":"force exerted by surrounding fluid"},{"key":"c","text":"force that acts in the opposite direction to the weight of an object submerged in a fluid"},{"key":"d","text":"force experienced by an object due to its weight in the absence of any fluid"}],"answer":"c","explanation":"Buoyancy is the net upward thrust of the surrounding fluid, equal to the weight of fluid displaced, acting opposite to the body's weight. The key selects (c).","marks":1,"source":{"kind":"past","set":8,"question":33,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q33 · 1 mark"},"topic":"ACiE0302"},{"id":"PAST-08-034","src":"PAST-08-034","text":"The momentum principle is not applicable to","options":[{"key":"a","text":"force on a plate"},{"key":"b","text":"force on a bend"},{"key":"c","text":"venturi meter"},{"key":"d","text":"force on a moving plate"}],"answer":"c","explanation":"Jet forces on plates and forces on pipe bends are found with the impulse–momentum equation. A venturimeter is analysed with Bernoulli's (energy) equation and continuity.","marks":1,"source":{"kind":"past","set":8,"question":34,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q34 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-08-037","src":"PAST-08-037","text":"The head loss formula h<sub>f</sub> = fLQ<sup>2</sup>/(12.1D<sup>5</sup>) is given by","options":[{"key":"a","text":"Darcy–Weisbach"},{"key":"b","text":"Hazen–Williams"},{"key":"c","text":"Chezy"},{"key":"d","text":"Manning"}],"answer":"a","explanation":"Substituting \\(V = \\dfrac{4Q}{\\pi D^2}\\) into \\(h_f = \\dfrac{fLV^2}{2gD}\\) gives \\[h_f = \\dfrac{8fLQ^2}{\\pi^2gD^5} \\approx \\dfrac{fLQ^2}{12.1D^5}\\] the Darcy-Weisbach equation in terms of discharge.","marks":1,"source":{"kind":"past","set":8,"question":37,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q37 · 1 mark"},"topic":"ACiE0304"},{"id":"PAST-08-045","src":"PAST-08-045","text":"The difference between the total head line and the hydraulic grade line represents the","options":[{"key":"a","text":"piezometric head"},{"key":"b","text":"pressure head"},{"key":"c","text":"elevation head"},{"key":"d","text":"velocity head"}],"answer":"d","explanation":"The TEL lies \\(\\dfrac{V^2}{2g}\\) above the HGL, so the vertical gap between them is the velocity head.","marks":1,"source":{"kind":"past","set":8,"question":45,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q45 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-08-059","src":"PAST-08-059","text":"The formula for sudden expansion loss is","options":[{"key":"a","text":"V<sup>2</sup>/2g"},{"key":"b","text":"kV<sup>2</sup>/2g"},{"key":"c","text":"V<sup>2</sup>/4g"},{"key":"d","text":"(V<sub>1</sub> − V<sub>2</sub>)<sup>2</sup>/2g"}],"answer":"d","explanation":"Applying momentum and energy (the Borda-Carnot result) to a sudden enlargement gives \\[h_L = \\dfrac{(V_1 - V_2)^2}{2g}\\]","marks":1,"source":{"kind":"past","set":8,"question":59,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q59 · 1 mark"},"topic":"ACiE0304"},{"id":"PAST-08-071","src":"PAST-08-071","text":"The pressure of the gas in a cylindrical chamber is P<sub>0</sub>. The vertical (axial) force exerted by the gas on its hemispherical end is","options":[{"key":"a","text":"πP<sub>0</sub>R<sup>2</sup>"},{"key":"b","text":"2πP<sub>0</sub>R<sup>2</sup>"},{"key":"c","text":"3πP<sub>0</sub>R<sup>2</sup>"},{"key":"d","text":"4πP<sub>0</sub>R<sup>2</sup>"}],"answer":"a","explanation":"The resultant pressure force on a curved surface in a given direction equals the pressure times the projected area. The hemisphere projects as a circle of area \\(\\pi R^2\\), so \\[F = \\pi P_0R^2\\]","marks":2,"source":{"kind":"past","set":8,"question":71,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q71 · 2 marks"},"topic":"ACiE0302"},{"id":"PAST-08-077","src":"PAST-08-077","text":"The wetted perimeter of a trapezoidal section with side slope z (H):1 (V), depth y and bed width B is","options":[{"key":"a","text":"B − 2y√(1+z<sup>2</sup>)"},{"key":"b","text":"B + 2y√(1+z<sup>2</sup>)"},{"key":"c","text":"B + y√(1+z<sup>2</sup>)"},{"key":"d","text":"None of these"}],"answer":"b","explanation":"The wetted perimeter is the bed plus two sloping sides, each of length \\(y\\sqrt{1 + z^2}\\): \\[P = B + 2y\\sqrt{1 + z^2}\\] (The paper repeats option (a) as (d); it is shown here as 'None of these'.)","marks":2,"source":{"kind":"past","set":8,"question":77,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q77 · 2 marks"},"topic":"ACiE0305"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-08-004","src":"PAST-08-004","text":"The ductility of a material …… with the increase in percentage reduction in area of a specimen under a tensile test.","options":[{"key":"a","text":"Increases"},{"key":"b","text":"Decreases"},{"key":"c","text":"Increases rapidly"},{"key":"d","text":"Remains constant"}],"answer":"a","explanation":"Percentage elongation and percentage reduction in area are both measures of ductility. A larger reduction in area (necking) means a more ductile material.","marks":1,"source":{"kind":"past","set":8,"question":4,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q4 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-08-008","src":"PAST-08-008","text":"The bending moment in an arch is zero when","options":[{"key":"a","text":"the line of thrust is parallel to the line of axis"},{"key":"b","text":"the line of thrust coincides with the line of axis"},{"key":"c","text":"the ends are fixed"},{"key":"d","text":"the ends are hinged"}],"answer":"b","explanation":"The moment at any section is H times the distance between the arch axis and the line of thrust. Where the two coincide, the arch is in pure compression with zero moment (a parabolic arch under UDL, for example).","marks":1,"source":{"kind":"past","set":8,"question":8,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q8 · 1 mark"},"topic":"ACiE0405"},{"id":"PAST-08-012","src":"PAST-08-012","text":"Which of the following doesn't have the same unit as modulus of elasticity?","options":[{"key":"a","text":"Modulus of rigidity"},{"key":"b","text":"Shear stress"},{"key":"c","text":"Pressure"},{"key":"d","text":"Section modulus"}],"answer":"d","explanation":"E, G, stress and pressure are all force per area (N per m<sup>2</sup>). Section modulus \\(Z = \\dfrac{I}{y}\\) has units of length cubed (m<sup>3</sup>).","marks":1,"source":{"kind":"past","set":8,"question":12,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q12 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-08-032","src":"PAST-08-032","text":"If two point loads act directly above the two supports of a simply supported beam","options":[{"key":"a","text":"no internal force develops"},{"key":"b","text":"only axial force is 0"},{"key":"c","text":"BM is max at midspan"},{"key":"d","text":"reaction is not developed"}],"answer":"a","explanation":"Loads applied directly over the supports pass straight into the reactions, so the beam carries no shear force or bending moment.","marks":1,"source":{"kind":"past","set":8,"question":32,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q32 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-08-043","src":"PAST-08-043","text":"In pure bending, the stress distribution in a beam is","options":[{"key":"a","text":"linear"},{"key":"b","text":"parabolic"},{"key":"c","text":"elliptical"},{"key":"d","text":"constant"}],"answer":"a","explanation":"By simple bending theory, \\[\\sigma = \\dfrac{My}{I}\\] varies linearly with distance from the neutral axis. Shear stress in a rectangular beam varies parabolically.","marks":1,"source":{"kind":"past","set":8,"question":43,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q43 · 1 mark"},"topic":"ACiE0403"},{"id":"PAST-08-053","src":"PAST-08-053","text":"Which one of the following is wrong with respect to the strain energy (real work) method for finding deflection?","options":[{"key":"a","text":"Deflection can be found only in the direction of load"},{"key":"b","text":"Deflection can be found at any point in the desired direction"},{"key":"c","text":"Deflection can be found only at the loaded point"},{"key":"d","text":"Structure should be subjected to a single concentrated load"}],"answer":"b","explanation":"Equating external work \\(\\dfrac{1}{2}P\\delta\\) to the strain energy gives the deflection only under a single concentrated load, in its own direction. Deflection at any point in any direction needs the unit-load (virtual work) method or Castigliano's theorem.","marks":1,"source":{"kind":"past","set":8,"question":53,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q53 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-08-054","src":"PAST-08-054","text":"The stiffness at the free (near) end of a member if the far end is fixed is","options":[{"key":"a","text":"4EI/L"},{"key":"b","text":"3EI/L"},{"key":"c","text":"2EI/L"},{"key":"d","text":"EI/L"}],"answer":"a","explanation":"A moment rotating the near end of a prismatic member through a unit angle, with the far end fixed, is 4EI/L; half of it (2EI/L) is carried over. It is 3EI/L when the far end is hinged.","marks":1,"source":{"kind":"past","set":8,"question":54,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q54 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-08-067","src":"PAST-08-067","text":"For given two hinged semicircular arches A, B and C of radii 5 m, 7.5 m and 10 m respectively, each carrying a concentrated crown load W, the ratio of horizontal thrusts at their supports will be","options":[{"key":"a","text":"1:1:1"},{"key":"b","text":"1:1.5:2"},{"key":"c","text":"2:1.5:1"},{"key":"d","text":"3:2:1.5"}],"answer":"a","explanation":"For a two-hinged semicircular arch with a central point load, \\[H = \\dfrac{W}{\\pi}\\] independent of the radius. All three thrusts are equal, in the ratio 1:1:1.","marks":2,"source":{"kind":"past","set":8,"question":67,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q67 · 2 marks"},"topic":"ACiE0406"},{"id":"PAST-08-074","src":"PAST-08-074","text":"What are the support reactions (at A and B) of a simply supported beam of span 1 m if a 1 kNm clockwise couple acts at midspan?","options":[{"key":"a","text":"1 kN upward, 1 kN downward"},{"key":"b","text":"1 kN downward, 1 kN upward"},{"key":"c","text":"2 kN upward, 2 kN downward"},{"key":"d","text":"2 kN downward, 2 kN upward"}],"answer":"b","explanation":"The reactions must form an equal and opposite (anticlockwise) couple: \\[R = \\dfrac{M}{L} = \\dfrac{1}{1} = 1\\ \\text{kN}\\] The left support A pulls down 1 kN and the right support B pushes up 1 kN.","marks":2,"source":{"kind":"past","set":8,"question":74,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q74 · 2 marks"},"topic":"ACiE0401"}]},{"name":"Design of Structures","questions":[{"id":"PAST-08-049","src":"PAST-08-049","text":"For reversal of stresses, the most suitable bolt is","options":[{"key":"a","text":"black bolt"},{"key":"b","text":"turned bolt"},{"key":"c","text":"friction grip bolt"},{"key":"d","text":"none of these"}],"answer":"c","explanation":"High-strength friction-grip bolts transfer load by clamping friction without slip, so they perform well under fatigue and stress reversal. Black bolts loosen and slip.","marks":1,"source":{"kind":"past","set":8,"question":49,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q49 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-08-050","src":"PAST-08-050","text":"The minimum % of reinforcement required for a footing with Fe415 grade steel is","options":[{"key":"a","text":"0.12"},{"key":"b","text":"0.15"},{"key":"c","text":"0.2"},{"key":"d","text":"0.8"}],"answer":"a","explanation":"Footings follow the slab minimum in IS 456: 0.12% of the gross area for HYSD (Fe415) bars and 0.15% for mild steel.","marks":1,"source":{"kind":"past","set":8,"question":50,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q50 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-08-051","src":"PAST-08-051","text":"The length required for full transfer of bar stress to concrete is called","options":[{"key":"a","text":"development length"},{"key":"b","text":"bond length"},{"key":"c","text":"equivalent length"},{"key":"d","text":"anchorage length"}],"answer":"a","explanation":"Development length is the embedded length needed to develop the full bar stress through bond: \\[L_d = \\dfrac{\\phi\\sigma_s}{4\\tau_{bd}}\\]","marks":1,"source":{"kind":"past","set":8,"question":51,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q51 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-08-058","src":"PAST-08-058","text":"The snow load is calculated as","options":[{"key":"a","text":"S = μS<sub>0</sub>"},{"key":"b","text":"S = μ/S<sub>0</sub>"},{"key":"c","text":"S<sub>0</sub> = μS"},{"key":"d","text":"S = μS<sub>0</sub><sup>2</sup>"}],"answer":"a","explanation":"IS 875 (Part 4) gives the roof snow load as \\[S = \\mu S_0\\] where \\(S_0\\) is the ground snow load and \\(\\mu\\) the shape coefficient.","marks":1,"source":{"kind":"past","set":8,"question":58,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q58 · 1 mark"},"topic":"ACiE0501"},{"id":"PAST-08-060","src":"PAST-08-060","text":"A thin hairline crack is also known as","options":[{"key":"a","text":"breaking"},{"key":"b","text":"sizzling"},{"key":"c","text":"crazing"},{"key":"d","text":"cracking"}],"answer":"c","explanation":"Crazing is a network of fine hairline cracks on the surface of concrete or plaster, caused by surface shrinkage.","marks":1,"source":{"kind":"past","set":8,"question":60,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q60 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-08-079","src":"PAST-08-079","text":"The permissible load in a circular column shouldn't exceed the permitted load in a …… of equivalent cross-sectional area.","options":[{"key":"a","text":"square column"},{"key":"b","text":"rectangular column"},{"key":"c","text":"trapezoidal column"},{"key":"d","text":"prismoidal column"}],"answer":"a","explanation":"The code rule caps the load on a circular column at the load allowed on a square column of the same cross-sectional area, even where spiral binding would otherwise permit more.","marks":2,"source":{"kind":"past","set":8,"question":79,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q79 · 2 marks"},"topic":"ACiE0503"},{"id":"PAST-08-080","src":"PAST-08-080","text":"A doubly reinforced section means","options":[{"key":"a","text":"steel in compression only"},{"key":"b","text":"steel in tension only"},{"key":"c","text":"steel in both compression and tension"},{"key":"d","text":"double steel in compression than tension"}],"answer":"c","explanation":"A doubly reinforced beam has designed steel in both the tension and the compression zones. It is used when the depth is restricted and M<sub>u</sub> exceeds M<sub>u,lim</sub>.","marks":2,"source":{"kind":"past","set":8,"question":80,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q80 · 2 marks"},"topic":"ACiE0503"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-08-011","src":"PAST-08-011","text":"In the process of finding fixed inorganic solids in a sludge sample, the temperature is","options":[{"key":"a","text":"550° ± 5° for 15 minutes"},{"key":"b","text":"550° ± 5° for 1 hr"},{"key":"c","text":"105° ± 5° for 15 minutes"},{"key":"d","text":"105° ± 5° for 1 hr"}],"answer":"a","explanation":"The dried residue (103–105°C) is ignited in a muffle furnace at about 550°C for at least 15 minutes. The volatile (organic) solids burn off, and the residue is the fixed solids.","marks":1,"source":{"kind":"past","set":8,"question":11,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q11 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-08-013","src":"PAST-08-013","text":"The DO value of fresh pond water at 20°C temperature, 760 mm of Hg pressure and zero salinity is","options":[{"key":"a","text":"9.08 mg/l"},{"key":"b","text":"8.2 mg/l"},{"key":"c","text":"14 mg/l"},{"key":"d","text":"7 mg/l"}],"answer":"a","explanation":"The saturation dissolved oxygen of fresh water at 20°C and 1 atm is about 9.1 mg/L. It is about 14.6 mg/L at 0°C and falls with rising temperature.","marks":1,"source":{"kind":"past","set":8,"question":13,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q13 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-08-020","src":"PAST-08-020","text":"What is EIA?","options":[{"key":"a","text":"Environmental Impact Assessment (EIA) is a method for promoting rapid project development without considering its potential impact on the environment"},{"key":"b","text":"EIA stands for Economic Investment Appraisal, focusing on financial considerations rather than environmental effects"},{"key":"c","text":"Environmental Impact Assessment (EIA) is a process that intentionally overlooks potential negative effects of a project on the surrounding ecosystem"},{"key":"d","text":"EIA is a systematic process used to evaluate the environmental consequences of a proposed project or development, aiming to identify and mitigate potential adverse effects on the environment"}],"answer":"d","explanation":"EIA systematically predicts and evaluates the environmental effects of a proposed project before approval and plans measures to avoid or mitigate the adverse ones.","marks":1,"source":{"kind":"past","set":8,"question":20,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q20 · 1 mark"},"topic":"ACiE0606"},{"id":"PAST-08-023","src":"PAST-08-023","text":"Turbidity of water is expressed","options":[{"key":"a","text":"in ppm"},{"key":"b","text":"in numbers in an arbitrary scale"},{"key":"c","text":"by pH value"},{"key":"d","text":"by colour code"}],"answer":"a","explanation":"Turbidity is conventionally expressed in ppm (mg/L) on the silica scale, where 1 unit is the turbidity of 1 mg SiO<sub>2</sub> per litre (now NTU by nephelometer).","marks":1,"source":{"kind":"past","set":8,"question":23,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q23 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-08-038","src":"PAST-08-038","text":"In the water-supply distribution network, which of the following is NOT a reason why the dead-end system is disfavoured?","options":[{"key":"a","text":"It is cumbersome in terms of design"},{"key":"b","text":"The pressure at the dead-ends becomes undesirably low in the case of additional extensions"},{"key":"c","text":"It is difficult to maintain residual chlorine levels at the dead ends"},{"key":"d","text":"At the time of repairs, service connections beyond the point of repair are deprived of water"}],"answer":"a","explanation":"The dead-end (tree) system is the simplest to design and analyse, so (a) is not a drawback. Low pressure after extensions, stagnant water that loses its chlorine residual, and whole areas cut off during repairs are its real disadvantages. The stem is reworded, because the paper asks why the system is not favoured, yet (b)–(d) are all valid reasons and the key is (a).","marks":1,"source":{"kind":"past","set":8,"question":38,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q38 · 1 mark"},"topic":"ACiE0602"},{"id":"PAST-08-040","src":"PAST-08-040","text":"Which of the following causes greasing in flocculation?","options":[{"key":"a","text":"Alum"},{"key":"b","text":"Surfactant"},{"key":"c","text":"Ammonia"},{"key":"d","text":"Chlorine"}],"answer":"b","explanation":"Surfactants (detergents) coat particles, cause foaming and greasy films, and hinder floc formation. Alum is the coagulant that aids flocculation.","marks":1,"source":{"kind":"past","set":8,"question":40,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q40 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-08-044","src":"PAST-08-044","text":"Demography is the study of","options":[{"key":"a","text":"population"},{"key":"b","text":"culture"},{"key":"c","text":"heritage"},{"key":"d","text":"environmental change"}],"answer":"a","explanation":"Demography is the statistical study of population size, structure, growth and distribution, which underlies population forecasting for water demand.","marks":1,"source":{"kind":"past","set":8,"question":44,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q44 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-08-078","src":"PAST-08-078","text":"Vulnerability analysis comes in which part of the disaster management cycle?","options":[{"key":"a","text":"Preparedness"},{"key":"b","text":"Response"},{"key":"c","text":"Recovery"},{"key":"d","text":"Mitigation"}],"answer":"d","explanation":"Hazard, vulnerability and risk assessment are carried out before a disaster, in the mitigation (risk-reduction) phase, to decide which measures are needed.","marks":2,"source":{"kind":"past","set":8,"question":78,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q78 · 2 marks"},"topic":"ACiE0606"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-08-003","src":"PAST-08-003","text":"A farm pond is used for","options":[{"key":"a","text":"Erosion control"},{"key":"b","text":"Flood control"},{"key":"c","text":"Water storage"},{"key":"d","text":"Runoff control"}],"answer":"c","explanation":"A farm pond is a small excavated or embanked reservoir that collects runoff and stores water for irrigation, livestock and domestic use in the dry period.","marks":1,"source":{"kind":"past","set":8,"question":3,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q3 · 1 mark"},"topic":"ACiE0701"},{"id":"PAST-08-010","src":"PAST-08-010","text":"Which of the following doesn't prevent water logging?","options":[{"key":"a","text":"Frequent irrigation"},{"key":"b","text":"Lining of canal"},{"key":"c","text":"Subsurface drainage installation"},{"key":"d","text":"Reducing FSL of canal"}],"answer":"a","explanation":"Frequent, excessive irrigation raises the water table and causes waterlogging. Lining, subsurface drains and a lower full supply level all control it.","marks":1,"source":{"kind":"past","set":8,"question":10,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q10 · 1 mark"},"topic":"ACiE0706"},{"id":"PAST-08-029","src":"PAST-08-029","text":"Which canal is not considered to be used for irrigation?","options":[{"key":"a","text":"Main canal"},{"key":"b","text":"Major distributary"},{"key":"c","text":"Minor distributary"},{"key":"d","text":"Watercourse"}],"answer":"a","explanation":"The main canal carries water from the headworks to the branch canals and distributaries and normally does no direct irrigation. The distributaries and watercourses feed the fields.","marks":1,"source":{"kind":"past","set":8,"question":29,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q29 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-08-030","src":"PAST-08-030","text":"The water available for plants is","options":[{"key":"a","text":"FC − PWP"},{"key":"b","text":"FC"},{"key":"c","text":"PWP"},{"key":"d","text":"RWW − PWP"}],"answer":"a","explanation":"Available moisture is the water held between field capacity and the permanent wilting point.","marks":1,"source":{"kind":"past","set":8,"question":30,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q30 · 1 mark"},"topic":"ACiE0701"},{"id":"PAST-08-031","src":"PAST-08-031","text":"A tile drain is suitable for","options":[{"key":"a","text":"dry soil"},{"key":"b","text":"black soil"},{"key":"c","text":"wet soil"},{"key":"d","text":"red soil"}],"answer":"c","explanation":"Tile (subsurface) drains lower a high water table and remove excess water from wet, waterlogged soils.","marks":1,"source":{"kind":"past","set":8,"question":31,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q31 · 1 mark"},"topic":"ACiE0706"},{"id":"PAST-08-042","src":"PAST-08-042","text":"Which of the following structures is constructed to separate the under sluices from the main weir?","options":[{"key":"a","text":"Marginal bund"},{"key":"b","text":"Divide wall"},{"key":"c","text":"Head regulator"},{"key":"d","text":"None of the above"}],"answer":"b","explanation":"The divide wall runs at right angles to the weir axis. It separates the undersluice pocket from the main weir, creating a still pocket in front of the canal head.","marks":1,"source":{"kind":"past","set":8,"question":42,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q42 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-08-056","src":"PAST-08-056","text":"The function of a cross regulator in irrigation is","options":[{"key":"a","text":"to maintain the head for flow in the off-taking canal"},{"key":"b","text":"to overflow excessive flow of water"},{"key":"c","text":"to regulate the water supplies in the distributaries"},{"key":"d","text":"all of the above"}],"answer":"a","explanation":"A cross regulator across the parent canal heads up the water level upstream, so that the off-taking channels draw their full supply even when the parent canal runs low.","marks":1,"source":{"kind":"past","set":8,"question":56,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q56 · 1 mark"},"topic":"ACiE0705"},{"id":"PAST-08-072","src":"PAST-08-072","text":"Calculate the RL of the top of the guide bund (bed level = 113 m, max flood depth = 5 m, max size of floating debris = 0.2 m, Q = 1600 m<sup>3</sup>/s, return period = 100 yr).","options":[{"key":"a","text":"120 m"},{"key":"b","text":"122 m"},{"key":"c","text":"118 m"},{"key":"d","text":"124 m"}],"answer":"a","explanation":"The HFL is \\(113 + 5 = 118\\) m. Adding a freeboard of about 1.5-2 m (covering waves and floating debris) gives a top level of about 120 m.","marks":2,"source":{"kind":"past","set":8,"question":72,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q72 · 2 marks"},"topic":"ACiE0704"},{"id":"PAST-08-073","src":"PAST-08-073","text":"Calculate Lane's creep length (u/s cutoff = 5 m, floor length = 54 m, d/s cutoff = 8 m).","options":[{"key":"a","text":"44 m"},{"key":"b","text":"57 m"},{"key":"c","text":"80 m"},{"key":"d","text":"54 m"}],"answer":"a","explanation":"Lane's weighted creep is the vertical creep plus one-third of the horizontal: \\[\\begin{aligned} L &amp;= 2 \\times 5 + \\dfrac{54}{3} + 2 \\times 8 \\\\ &amp;= 10 + 18 + 16 = 44\\ \\text{m} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":8,"question":73,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q73 · 2 marks"},"topic":"ACiE0703"}]},{"name":"Hydropower","questions":[{"id":"PAST-08-017","src":"PAST-08-017","text":"The pressure at the inlet and outlet of a draft tube shouldn't be","options":[{"key":"a","text":"less than one third of atmospheric pressure"},{"key":"b","text":"greater than one third of atmospheric pressure"},{"key":"c","text":"less than 1 atm"},{"key":"d","text":"greater than 1 atm"}],"answer":"a","explanation":"The draft tube works below atmospheric pressure, but if the absolute pressure at its inlet falls too low (below about one-third of an atmosphere) dissolved air and vapour come out and cause cavitation. This limits the suction head.","marks":1,"source":{"kind":"past","set":8,"question":17,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q17 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-08-022","src":"PAST-08-022","text":"What is the function of a surge tank?","options":[{"key":"a","text":"to reduce the effects of pressure"},{"key":"b","text":"to control velocity"},{"key":"c","text":"to store water"},{"key":"d","text":"to reduce pipe diameter"}],"answer":"a","explanation":"A surge tank absorbs the water-hammer pressure rise on load rejection and supplies water on sudden demand, reducing the pressure effects on the conduit.","marks":1,"source":{"kind":"past","set":8,"question":22,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q22 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-08-052","src":"PAST-08-052","text":"The power available continuously is","options":[{"key":"a","text":"firm power"},{"key":"b","text":"secondary power"},{"key":"c","text":"plant power"},{"key":"d","text":"water power"}],"answer":"a","explanation":"Firm (primary) power is the power available at all times, even in the driest period. Power available only part of the time is secondary power.","marks":1,"source":{"kind":"past","set":8,"question":52,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q52 · 1 mark"},"topic":"ACiE0802"},{"id":"PAST-08-066","src":"PAST-08-066","text":"What is the minimum submergence that should be provided for a forebay with Q = 3.6 m<sup>3</sup>/s and (penstock) D = 1.55 m?","options":[{"key":"a","text":"0.3"},{"key":"b","text":"1.3"},{"key":"c","text":"2.3"},{"key":"d","text":"3.3"}],"answer":"b","explanation":"The penstock velocity is \\[V = \\dfrac{3.6}{\\pi \\times 1.55^2{/}4} = 1.91\\ \\text{m/s}\\] Gordon's formula \\(S = cV\\sqrt{D}\\) with \\(c = 0.5434\\) (symmetric approach) gives \\[\\begin{aligned} S &amp;= 0.5434 \\times 1.91 \\times \\sqrt{1.55} \\\\ &amp;\\approx 1.3\\ \\text{m} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":8,"question":66,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q66 · 2 marks"},"topic":"ACiE0804"},{"id":"PAST-08-075","src":"PAST-08-075","text":"Power calculation (H = 423.5 m, head loss = 2.5 m, Q = 0.9 m<sup>3</sup>/s, η = 85%)","options":[{"key":"a","text":"3159.45 kW"},{"key":"b","text":"3159.45 W"},{"key":"c","text":"3159.45 MW"},{"key":"d","text":"31594.5 kW"}],"answer":"a","explanation":"The power is \\[\\begin{aligned} P &amp;= \\eta\\gamma QH_{net} \\\\ &amp;= 0.85 \\times 9.81 \\times 0.9 \\\\ &amp;\\quad \\times (423.5 - 2.5) \\\\ &amp;\\approx 3159.45\\ \\text{kW} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":8,"question":75,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q75 · 2 marks"},"topic":"ACiE0802"},{"id":"PAST-08-076","src":"PAST-08-076","text":"A morning glory is the","options":[{"key":"a","text":"special flared inlet of the shaft spillway of a dam of very small height"},{"key":"b","text":"special flared inlet of the shaft spillway of a large dam project"},{"key":"c","text":"horizontal tunnel constructed in a shaft spillway across the body of a gravity dam to carry surplus reservoir water to the d/s river"},{"key":"d","text":"horizontal tunnel constructed in a shaft spillway of an earthen dam through its foundation to carry surplus reservoir water to the d/s river"}],"answer":"b","explanation":"A morning-glory (bell-mouth) spillway is the funnel-shaped flared crest at the top of a vertical shaft spillway. It is used at large dams where there is no room for an open spillway. The horizontal tunnel below is the outlet conduit.","marks":2,"source":{"kind":"past","set":8,"question":76,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q76 · 2 marks"},"topic":"ACiE0803"}]},{"name":"Transportation","questions":[{"id":"PAST-08-009","src":"PAST-08-009","text":"A drainage structure parallel to the road, provided to intercept rain in a hilly region, is a","options":[{"key":"a","text":"Catch drain"},{"key":"b","text":"Side drain"},{"key":"c","text":"Sloping drain"},{"key":"d","text":"Cross drain"}],"answer":"a","explanation":"A catch-water drain runs higher up the hill slope, parallel to the road, and intercepts the runoff before it reaches the cut slope and carriageway.","marks":1,"source":{"kind":"past","set":8,"question":9,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q9 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-08-014","src":"PAST-08-014","text":"Which premix is used in a base course?","options":[{"key":"a","text":"Otta seal"},{"key":"b","text":"Bituminous concrete"},{"key":"c","text":"Bituminous bound macadam"},{"key":"d","text":"Surface dressing"}],"answer":"c","explanation":"Bituminous (bound) macadam is an open-graded premix used as a base or binder course. Bituminous concrete is a dense wearing course, while Otta seal and surface dressing are thin surfacings.","marks":1,"source":{"kind":"past","set":8,"question":14,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q14 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-08-035","src":"PAST-08-035","text":"The minimum bitumen ductility value to be used in roads is","options":[{"key":"a","text":"50 cm"},{"key":"b","text":"40 cm"},{"key":"c","text":"30 cm"},{"key":"d","text":"60 cm"}],"answer":"a","explanation":"Paving bitumen should have a ductility of at least 50 cm (75–100 cm for many grades), measured at 27°C and 50 mm/min. The paper prints the values in mm, but ductility is reported in cm.","marks":1,"source":{"kind":"past","set":8,"question":35,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q35 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-08-039","src":"PAST-08-039","text":"A road inside a city is called a","options":[{"key":"a","text":"street"},{"key":"b","text":"ring road"},{"key":"c","text":"highway"},{"key":"d","text":"trunk road"}],"answer":"a","explanation":"Urban roads serving local traffic and giving access to buildings are streets. Highways and trunk roads are inter-city routes.","marks":1,"source":{"kind":"past","set":8,"question":39,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q39 · 1 mark"},"topic":"ACiE0901"},{"id":"PAST-08-046","src":"PAST-08-046","text":"The minimum weaving angle in a rotary is","options":[{"key":"a","text":"10°"},{"key":"b","text":"15°"},{"key":"c","text":"20°"},{"key":"d","text":"25°"}],"answer":"b","explanation":"The weaving angle is kept small for easy merging, but at least about 15° (usually up to 30–40°), so that vehicles can weave safely.","marks":1,"source":{"kind":"past","set":8,"question":46,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q46 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-08-068","src":"PAST-08-068","text":"Which percentile value of CBR is used for the design of a road with more than 20 million ESAL, as recommended by DoR?","options":[{"key":"a","text":"87.5%"},{"key":"b","text":"90%"},{"key":"c","text":"85%"},{"key":"d","text":"75%"}],"answer":"b","explanation":"For heavy traffic (above about 20 msa), the 90th percentile subgrade CBR is adopted, so 90% of the tested sections are at least as strong. Lighter traffic uses the 80th percentile.","marks":2,"source":{"kind":"past","set":8,"question":68,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q68 · 2 marks"},"topic":"ACiE0905"},{"id":"PAST-08-069","src":"PAST-08-069","text":"What is the impact value of an aggregate if the total weight is 300 gm and the weight retained on the 2.36 mm sieve is 180 gm?","options":[{"key":"a","text":"40%"},{"key":"b","text":"35%"},{"key":"c","text":"45%"},{"key":"d","text":"30%"}],"answer":"a","explanation":"AIV is the fines passing 2.36 mm as a percentage of the total: \\[\\begin{aligned} \\text{AIV} &amp;= \\dfrac{300 - 180}{300} \\times 100 \\\\ &amp;= 40\\% \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":8,"question":69,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q69 · 2 marks"},"topic":"ACiE0903"},{"id":"PAST-08-070","src":"PAST-08-070","text":"In the LA abrasion test, 1.88 kg out of 5 kg passed through the 1.7 mm sieve. The aggregate is then suitable for","options":[{"key":"a","text":"bituminous penetration macadam"},{"key":"b","text":"dense bituminous macadam"},{"key":"c","text":"bituminous surface course"},{"key":"d","text":"surface dressing"}],"answer":"a","explanation":"The LA abrasion value is \\[\\dfrac{1.88}{5} \\times 100 = 37.6\\%\\] This exceeds the 30-35% limits for bituminous concrete, DBM and surface dressing but is within the 40% limit for penetration macadam.","marks":2,"source":{"kind":"past","set":8,"question":70,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q70 · 2 marks"},"topic":"ACiE0903"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-08-001","src":"PAST-08-001","text":"Who was the first registrar of NEC?","options":[{"key":"a","text":"Bindeshwar Yadav"},{"key":"b","text":"Padma Bahadur Shahi"},{"key":"c","text":"Shiw Mangal Giri"},{"key":"d","text":"Hari Bahadur Darlami"}],"answer":"a","explanation":"Er. Bindeshwor Yadav was the first Registrar of the Nepal Engineering Council. Er. Ram Babu Sharma was its first chairman.","marks":1,"source":{"kind":"past","set":8,"question":1,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q1 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-08-002","src":"PAST-08-002","text":"Which of the following is true about a dummy?","options":[{"key":"a","text":"It doesn't consume resources"},{"key":"b","text":"It doesn't have head and tail event"},{"key":"c","text":"It can be added anywhere in the network"},{"key":"d","text":"It simplifies the network"}],"answer":"a","explanation":"A dummy is a zero-duration activity that uses no time or resources. It only shows a dependency or gives parallel activities unique event numbers, and it does have head and tail events.","marks":1,"source":{"kind":"past","set":8,"question":2,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q2 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-08-015","src":"PAST-08-015","text":"The assessment done by the implementing agency to check the eligibility of a firm to carry out the contract is","options":[{"key":"a","text":"Pre-qualification"},{"key":"b","text":"Tender assessment"},{"key":"c","text":"Post-qualification"},{"key":"d","text":"Contract assessment"}],"answer":"a","explanation":"Pre-qualification screens firms on experience, capacity, equipment and finances before bidding, so only eligible firms may tender. Post-qualification checks the lowest bidder after evaluation.","marks":1,"source":{"kind":"past","set":8,"question":15,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q15 · 1 mark"},"topic":"AALL1004"},{"id":"PAST-08-055","src":"PAST-08-055","text":"The size of the letter means the …… of the letter.","options":[{"key":"a","text":"thickness"},{"key":"b","text":"height"},{"key":"c","text":"length"},{"key":"d","text":"width"}],"answer":"b","explanation":"In engineering lettering, the size of a letter is specified by its height (for example 3.5, 5 or 7 mm).","marks":1,"source":{"kind":"past","set":8,"question":55,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q55 · 1 mark"},"topic":"AALL1001"},{"id":"PAST-08-057","src":"PAST-08-057","text":"The time value of money is the relation between","options":[{"key":"a","text":"money and time"},{"key":"b","text":"time and interest"},{"key":"c","text":"interest and money"},{"key":"d","text":"time and inflation"}],"answer":"a","explanation":"Money available now is worth more than the same amount later because it can earn interest. The time value of money expresses how value changes with time.","marks":1,"source":{"kind":"past","set":8,"question":57,"marks":1,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q57 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-08-061","src":"PAST-08-061","text":"The top view of an orthographic drawing lies on","options":[{"key":"a","text":"HP"},{"key":"b","text":"VP"},{"key":"c","text":"PP"},{"key":"d","text":"All"}],"answer":"a","explanation":"The top view (plan) is projected onto the horizontal plane (HP). The front view goes on the VP and the side view on the profile plane (PP).","marks":2,"source":{"kind":"past","set":8,"question":61,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q61 · 2 marks"},"topic":"AALL1001"},{"id":"PAST-08-063","src":"PAST-08-063","text":"The definition of a Non-Nepali engineer according to NEC is","options":[{"key":"a","text":"a non-Nepali engineer working under engineering institutions"},{"key":"b","text":"a Nepali engineer working abroad"},{"key":"c","text":"a freelancer engineer"},{"key":"d","text":"a Nepali engineer working under engineering institutions"}],"answer":"a","explanation":"The Act treats a foreign (non-Nepali) citizen engineer working in Nepal, for example under an engineering institution or project, as a non-Nepali engineer. Such an engineer must also register with NEC.","marks":2,"source":{"kind":"past","set":8,"question":63,"marks":2,"date":"2080 Mangsir 22","shift":"3rd shift","reference":"Past Paper Set 8, Q63 · 2 marks"},"topic":"AALL1006"}]}]};
